/* Subtle depth for Bootstrap buttons */
.btn {
  --btn-depth-color: rgba(0, 0, 0, 0.18);
  border-width: 1px;
  border-style: solid;
  border-radius: 0.4rem;
  font-weight: 500;
  transition: transform 120ms ease, box-shadow 120ms ease, background-color 120ms ease, border-color 120ms ease;
  box-shadow: 0 2px 0 var(--btn-depth-color), 0 3px 6px rgba(0, 0, 0, 0.07);
}

.btn:hover:not(:disabled):not(.disabled) {
  transform: translateY(-1px);
  box-shadow: 0 3px 0 var(--btn-depth-color), 0 5px 9px rgba(0, 0, 0, 0.1);
}

.btn:active:not(:disabled):not(.disabled),
.btn.active {
  transform: translateY(1px);
  box-shadow: 0 0 0 var(--btn-depth-color), 0 1px 2px rgba(0, 0, 0, 0.08);
}

/* Keep keyboard focus visible */
.btn:focus-visible {
  outline: 2px solid var(--bs-primary);
  outline-offset: 3px;
}

/* Disabled buttons should not appear raised */
.btn:disabled,
.btn.disabled {
  transform: none;
  box-shadow: none;
  cursor: not-allowed;
}

/* Smaller buttons: less pronounced depth */
.btn-sm, .btn-group-sm > .btn {
  border-radius: 0.3rem;
  box-shadow: 0 1px 0 var(--btn-depth-color);
}

/* Larger buttons */
.btn-lg, .btn-group-lg > .btn {
  border-radius: 0.5rem;
  box-shadow: 0 3px 0 var(--btn-depth-color), 0 4px 8px rgba(0, 0, 0, 0.07);
}

/* Respect reduced-motion preferences */
@media (prefers-reduced-motion: reduce) {
  .btn {
    transition: none;
  }
}
/* Bootstrap button depth */
.btn {
  --btn-shadow-top: rgba(255, 255, 255, 0.20);
  --btn-shadow-bottom: rgba(0, 0, 0, 0.22);
  border-radius: 0.4rem;
  border: 1px solid rgba(0, 0, 0, 0.12);
  box-shadow: 0 -2px 0 var(--btn-shadow-top), 0 3px 0 var(--btn-shadow-bottom), 0 4px 7px rgba(0, 0, 0, 0.1);
  transition: transform 120ms ease, box-shadow 120ms ease, filter 120ms ease;
}

/* Use Bootstrap theme colors */
.btn-primary {
  --btn-shadow-top: rgba(var(--bs-primary-rgb), 0.35);
  --btn-shadow-bottom: rgba(var(--bs-primary-rgb), 0.75);
}

.btn-secondary {
  --btn-shadow-top: rgba(var(--bs-secondary-rgb), 0.35);
  --btn-shadow-bottom: rgba(var(--bs-secondary-rgb), 0.75);
}

.btn-success {
  --btn-shadow-top: rgba(var(--bs-success-rgb), 0.35);
  --btn-shadow-bottom: rgba(var(--bs-success-rgb), 0.75);
}

.btn-info {
  --btn-shadow-top: rgba(var(--bs-info-rgb), 0.35);
  --btn-shadow-bottom: rgba(var(--bs-info-rgb), 0.75);
}

.btn-warning {
  --btn-shadow-top: rgba(var(--bs-warning-rgb), 0.35);
  --btn-shadow-bottom: rgba(var(--bs-warning-rgb), 0.75);
}

.btn-danger {
  --btn-shadow-top: rgba(var(--bs-danger-rgb), 0.35);
  --btn-shadow-bottom: rgba(var(--bs-danger-rgb), 0.75);
}

/* Hover: lift the button */
.btn:hover:not(:disabled):not(.disabled) {
  transform: translateY(-1px);
  box-shadow: 0 -2px 0 var(--btn-shadow-top), 0 4px 0 var(--btn-shadow-bottom), 0 6px 10px rgba(0, 0, 0, 0.14);
  filter: brightness(1.05);
}

/* Press: remove the raised effect */
.btn:active:not(:disabled):not(.disabled) {
  transform: translateY(2px);
  box-shadow: 0 -1px 0 var(--btn-shadow-top), 0 1px 0 var(--btn-shadow-bottom);
  filter: none;
}

/* Disabled */
.btn:disabled,
.btn.disabled {
  transform: none;
  box-shadow: none;
  filter: none;
}

